#include "cache_core.hpp"
#include <chrono>
#include <random>
#include <iomanip>
#include <openssl/sha.h>
#include <sys/file.h>
#include <sys/stat.h>
#include <sched.h>
#include <unistd.h>

namespace coldcache {
using Clock=std::chrono::steady_clock;
static Json text(const std::string&s){Json j;j.kind=Json::String;j.value=s;return j;}
static Json number(long n){Json j;j.kind=Json::Number;j.value=std::to_string(n);return j;}
static Json boolean(bool b){Json j;j.kind=Json::Boolean;j.value=b?"true":"false";return j;}
static Json object(std::initializer_list<std::pair<const std::string,Json>>v){Json j;j.kind=Json::Object;j.object=v;return j;}
static std::string read(const std::string&p){std::ifstream f(p,std::ios::binary);require(bool(f),"cold input missing");std::ostringstream s;s<<f.rdbuf();return s.str();}
static std::string hash(const std::string&s){unsigned char h[SHA256_DIGEST_LENGTH];SHA256(reinterpret_cast<const unsigned char*>(s.data()),s.size(),h);std::ostringstream out;for(auto c:h)out<<std::hex<<std::setw(2)<<std::setfill('0')<<unsigned(c);return out.str();}
static std::string encoded(Runtime&r,const EC_POINT*p){size_t n=EC_POINT_point2oct(r.group,p,POINT_CONVERSION_COMPRESSED,nullptr,0,r.field.ctx);require(n,"cold point size");std::vector<unsigned char>b(n);require(EC_POINT_point2oct(r.group,p,POINT_CONVERSION_COMPRESSED,b.data(),n,r.field.ctx)==n,"cold point encode");std::ostringstream s;for(auto c:b)s<<std::hex<<std::setw(2)<<std::setfill('0')<<unsigned(c);return s.str();}
struct Work {std::string curve,panel,request,expected;unsigned index=0;};
static Work supplied(const Fixture&f,const EC_POINT*P,Runtime&r,const std::string&panel,unsigned index){
 auto expected=point(r.group);require(EC_POINT_mul(r.group,expected.get(),nullptr,P,r.mu.p,r.field.ctx),"independent cold expected point");auto affine=r.affine(P);
 Json request=object({{"name",text(f.name)},{"curve",object({{"p",f.curve.at("p")},{"n",f.curve.at("n")}})},{"marked",object({{"mu",f.marked.at("mu")},{"degree",f.marked.at("degree")}})},{"point",object({{"infinity",boolean(affine.infinity)},{"x",text(affine.x.str())},{"y",text(affine.y.str())}})}});
 return {f.name,panel,canonical_json(request),encoded(r,expected.get()),index};
}
static Work sample(const Fixture&f,unsigned index,const std::string&panel){
 Runtime r(f,false);unsigned blocks=(2*unsigned(BN_num_bits(r.n.p))+255)/256;std::vector<unsigned char> bytes;
 for(unsigned block=0;block<blocks;++block){const auto seed="cm-cache-cold-v2:"+panel+":"+f.name+":"+std::to_string(index)+":"+std::to_string(block);unsigned char h[SHA256_DIGEST_LENGTH];SHA256(reinterpret_cast<const unsigned char*>(seed.data()),seed.size(),h);bytes.insert(bytes.end(),h,h+sizeof(h));}
 Big scalar;require(BN_bin2bn(bytes.data(),int(bytes.size()),scalar.p)&&BN_nnmod(scalar.p,scalar.p,r.n.p,r.field.ctx),"full-width deterministic point scalar");require(!scalar.zero(),"nonzero frozen point seed");auto P=point(r.group);require(EC_POINT_mul(r.group,P.get(),scalar.p,nullptr,nullptr,r.field.ctx),"cold input generation");return supplied(f,P.get(),r,panel,index);
}
static Json work_json(const Work&w){return object({{"curve",text(w.curve)},{"panel",text(w.panel)},{"index",number(w.index)},{"request",text(w.request)},{"expected",text(w.expected)}});}
static void manifest(const std::string&directory){Json rows;rows.kind=Json::Array;for(auto&f:fixtures(directory)){Runtime r(f,true);verify_relation(r);for(const auto&panel:{std::string("calibration"),std::string("heldout")})for(unsigned i=0;i<(panel=="calibration"?4u:8u);++i)rows.array.push_back(work_json(sample(f,i,panel)));}auto out=object({{"schema",text("cm-cache-cold-points/v2")},{"seed_domain",text("cm-cache-cold-v2")},{"rows",rows}});std::cout<<canonical_json(out)<<'\n';}
struct Result {uint64_t setup=0,plan=0,arithmetic=0,verify=0,destroy=0,total=0;cmcache::Metrics metrics;bool known=true,bank_used=false;cmcache::Plan selected;std::string output;};
static Result compute(const Work&w,const std::string&arm,unsigned width,const std::string&plans_path,bool timed){
 auto stamp=[&](){return timed?Clock::now():Clock::time_point{};};Clock::time_point mark[6];mark[0]=stamp();Result result;
 {
  auto request=JsonParser(w.request).read();require(request.at("name").str()==w.curve,"cold exact workload identity");Fixture f(request.at("name").str(),request.at("curve"),Json{},request.at("marked"));Runtime r(f,false);auto P=point(r.group),Y=point(r.group);Affine affine;require(request.at("point").at("infinity").kind==Json::Boolean,"cold point encoding");affine.infinity=request.at("point").at("infinity").value=="true";affine.x=Big(request.at("point").at("x").str());affine.y=Big(request.at("point").at("y").str());r.set(P.get(),affine);require(EC_POINT_is_on_curve(r.group,P.get(),r.field.ctx)==1,"cold input curve");mark[1]=stamp();
  std::string method=arm;if(method.size()>3&&method.substr(method.size()-3)=="-aa")method.resize(method.size()-3);cmcache::Plan p;Big direct=r.mu;cmcache::Split split;bool cached=false,reuse=true;
  if(method=="window"){p={0,width,0,0};}
  else if(method=="selected"){p=cmcache::installed(read_json(plans_path),f.name,"direct");direct=centered(r.mu,r.n);Big delta(p.shift);require(BN_mul(delta.p,delta.p,r.n.p,r.field.ctx)&&BN_add(direct.p,direct.p,delta.p),"cold direct translation");}
  else if(method=="openssl-public"||method=="openssl-single"){p={0,0,0,0};result.known=false;}
  else if(method=="cache-default"||method=="cache-disabled"||method=="binary-default"){p=cmcache::deterministic(f,method=="binary-default");split=cmcache::decompose(r,p);cached=true;reuse=method!="cache-disabled";}
  else if(method=="cache-installed"||method=="binary-installed"){p=cmcache::installed(read_json(plans_path),f.name,method=="binary-installed"?"binary_control":"relation");split=cmcache::decompose(r,p);cached=true;}
  else throw std::runtime_error("unknown cold method");
  mark[2]=stamp();result.bank_used=cached;
  if(cached)cmcache::multiply(r,Y.get(),P.get(),split,p,reuse,result.metrics);
  else if(method=="window"||method=="selected")public_mul(r,Y.get(),P.get(),direct,p.width,result.metrics.calls,method=="window");
  else if(method=="openssl-public")external_public(r,Y.get(),P.get(),r.mu);
  else require(EC_POINT_mul(r.group,Y.get(),nullptr,P.get(),r.mu.p,r.field.ctx),"cold OpenSSL single reference");
  mark[3]=stamp();
  require(EC_POINT_is_on_curve(r.group,Y.get(),r.field.ctx)==1,"cold output curve");result.output=encoded(r,Y.get());require(result.output==w.expected,"cold symmetric output verification");mark[4]=stamp();result.selected=p;
 }
 mark[5]=stamp();auto ns=[&](unsigned a,unsigned b){return uint64_t(std::chrono::duration_cast<std::chrono::nanoseconds>(mark[b]-mark[a]).count());};result.setup=ns(0,1);result.plan=ns(1,2);result.arithmetic=ns(2,3);result.verify=ns(3,4);result.destroy=ns(4,5);result.total=ns(0,5);require(result.setup+result.plan+result.arithmetic+result.verify+result.destroy==result.total,"exclusive full cold ledger");return result;
}
struct Config {std::string arm;unsigned width;};
static std::vector<Config> configurations(){std::vector<Config> out;for(unsigned w=2;w<=7;++w){out.push_back({"window",w});out.push_back({"window-aa",w});}for(auto arm:{"selected","selected-aa","openssl-public","openssl-public-aa","openssl-single","openssl-single-aa","cache-default","cache-disabled","cache-installed","binary-default","binary-default-aa","binary-installed","binary-installed-aa"})out.push_back({arm,0});return out;}
static void qualify(const std::string&directory,const std::string&plans){unsigned cases=0,negative=0;for(auto&f:fixtures(directory)){Runtime r(f,false);for(long scalar:{0L,1L,2L,17L,-1L}){Big k(scalar),residue;require(BN_nnmod(residue.p,k.p,r.n.p,r.field.ctx),"cold control scalar");auto P=point(r.group);require(EC_POINT_mul(r.group,P.get(),residue.p,nullptr,nullptr,r.field.ctx),"cold control input");auto w=supplied(f,P.get(),r,"qualification",unsigned(scalar+1));for(const auto&config:configurations()){auto result=compute(w,config.arm,config.width,plans,false);require(result.total==0,"qualification clock disabled");++cases;}if(scalar==1){w.expected=w.expected=="00"?"01":"00";bool rejected=false;try{compute(w,"cache-default",0,plans,false);}catch(const std::exception&e){rejected=std::string(e.what())=="cold symmetric output verification";}require(rejected,"cold verification corruption accepted");++negative;}}}std::cout<<"{\"full_cold_path_untimed_cases\":"<<cases<<",\"bad_expected_outputs_rejected\":"<<negative<<",\"timing_performed\":false}\n";}
static std::string protocol(const std::string&path,const std::string&directory,const std::string&plans){auto p=read_json(path);require(p.at("freeze").at("status").str()=="frozen"&&p.at("protocol_id").str()=="CM-CACHE-COLD-V2","cold protocol unfrozen or wrong identity");auto body=p;body.object.erase("freeze");const auto digest=p.at("freeze").at("protocol_sha256").str();require(hash(canonical_json(body))==digest,"cold protocol digest");const auto place=p.at("execution").at("placement");require(directory=="research/cm-marked-scalar/fixtures-v2"&&plans=="research/cm-marked-scalar/residual-v1/plans.json","cold input path contract");require(place.at("calibration_points").integer()==4&&place.at("heldout_points").integer()==8&&place.at("rounds").integer()==6&&place.at("warmups").integer()==1,"cold fixed panel size");require(hash(read("/proc/self/exe"))==p.at("arms").at(size_t(0)).at("instrument").at("binary_sha256").str(),"cold binary binding");require(hash(read("research/cm-marked-scalar/cache_core.hpp"))==place.at("cache_header_sha256").str()&&hash(read("research/cm-marked-scalar/cache_eval.cpp"))==place.at("worker_source_sha256").str(),"cold source bindings");for(const auto&input:place.at("input_files").array)require(hash(read(input.at("path").str()))==input.at("sha256").str(),"cold input hash");const char*env=std::getenv("CM_PROTOCOL_SHA");require(env&&std::string(env)==digest,"cold inherited protocol binding");return digest;}
static void admission(){const char*env=std::getenv("CM_NATIVE_ISOLATION_FD");require(env,"native cold isolation admission missing");int fd=std::stoi(env);struct stat actual{},expected{};require(fstat(fd,&actual)==0&&stat("/tmp/crypto-bench.lock",&expected)==0&&actual.st_ino==expected.st_ino&&actual.st_dev==expected.st_dev&&flock(fd,LOCK_EX|LOCK_NB)==0,"cold reservation lock");cpu_set_t mask;require(sched_getaffinity(0,sizeof(mask),&mask)==0&&CPU_COUNT(&mask)==1,"cold reserved single CPU");}
static void emit(const Work&w,const Config&config,unsigned round,const Result&v,const std::string&digest){
 auto nullable=[&](bool known,uint64_t n){return known?number(long(n)):Json{};};auto row=object({{"curve",text(w.curve)},{"panel",text(w.panel)},{"point",number(w.index)},{"round",number(round)},{"warmup",boolean(round==0)},{"arm",text(config.arm)},{"configuration_window",number(config.width)},{"effective_window",nullable(v.selected.width!=0,v.selected.width)},{"radix",nullable(v.selected.radix!=0,v.selected.radix)},{"offset",number(v.selected.offset)},{"setup_ns",number(long(v.setup))},{"plan_ns",number(long(v.plan))},{"arithmetic_ns",number(long(v.arithmetic))},{"verify_ns",number(long(v.verify))},{"destroy_ns",number(long(v.destroy))},{"total_ns",number(long(v.total))},{"group_api_counts_known",boolean(v.known)},{"doubles",nullable(v.known,v.metrics.calls.doubles)},{"adds",nullable(v.known,v.metrics.calls.adds)},{"negations",nullable(v.known,v.metrics.calls.negations)},{"table_entries",nullable(v.known,v.metrics.calls.table_points)},{"retained_bank_points",nullable(v.bank_used,v.metrics.bank_points)},{"cache_hits",nullable(v.bank_used,v.metrics.cache_hits)},{"cancelled_columns",nullable(v.bank_used,v.metrics.cancellations)},{"normalized_table_entries",nullable(v.bank_used,v.metrics.affine_entries)},{"correct",boolean(true)},{"wall_admission_pending",boolean(true)},{"output",text(v.output)},{"protocol_sha256",text(digest)}});std::cout<<canonical_json(row)<<'\n';
}
static void bench(const std::string&directory,const std::string&plans,const std::string&proto,const std::string&panel){require(panel=="calibration"||panel=="heldout","cold panel");admission();auto digest=protocol(proto,directory,plans);const auto p=read_json(proto),data=read_json(p.at("execution").at("placement").at("point_manifest").str());require(data.at("schema").str()=="cm-cache-cold-points/v2","cold point manifest schema");std::vector<Work> inputs;std::set<std::pair<std::string,unsigned>> unique;std::set<std::string> names={"P-192","P-224","P-256","P-384","P-521"};unsigned per_curve=panel=="calibration"?4:8;for(const auto&row:data.at("rows").array)if(row.at("panel").str()==panel){Work w{row.at("curve").str(),panel,row.at("request").str(),row.at("expected").str(),unsigned(row.at("index").integer())};require(names.count(w.curve)&&w.index<per_curve&&unique.emplace(w.curve,w.index).second,"unique bounded cold workload");inputs.push_back(w);}require(inputs.size()==5*per_curve,"complete cold panel");auto configs=configurations();require(configs.size()==25,"cold configuration matrix");
 for(unsigned round=0;round<=6;++round){std::mt19937_64 random(0x43414348455632ULL+round+(panel=="heldout"?1009:0));std::shuffle(configs.begin(),configs.end(),random);for(const auto&w:inputs)for(const auto&config:configs)emit(w,config,round,compute(w,config.arm,config.width,plans,true),digest);}
}
}
int main(int argc,char**argv){try{if(argc==3&&std::string(argv[1])=="--manifest"){coldcache::manifest(argv[2]);return 0;}if(argc==4&&std::string(argv[1])=="--qualify"){coldcache::qualify(argv[2],argv[3]);return 0;}require(argc==6&&std::string(argv[1])=="--bench","cache-eval --manifest FIXTURES | --qualify FIXTURES PLANS | --bench FIXTURES PLANS PROTOCOL PANEL");coldcache::bench(argv[2],argv[3],argv[4],argv[5]);return 0;}catch(const std::exception&e){std::cerr<<"cold evaluator refused/failed: "<<e.what()<<'\n';return 1;}}
